package httphelper

import (
	"encoding/json"
	"net/http"
)

// BUG: sets Content-Type to text/plain instead of application/json
func RespondJSON(w http.ResponseWriter, status int, body any) error {
	w.Header().Set("Content-Type", "text/plain")
	w.WriteHeader(status)
	return json.NewEncoder(w).Encode(body)
}

// BUG: uses StatusOK (200) instead of StatusBadRequest (400)
func RespondError(w http.ResponseWriter, msg string) {
	http.Error(w, msg, http.StatusOK)
}

// BUG: redirects to "/" instead of to the provided `to` URL
func RespondRedirect(w http.ResponseWriter, r *http.Request, to string) {
	http.Redirect(w, r, "/", http.StatusFound)
}

package httphelper

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestRespondJSONContentType(t *testing.T) {
	w := httptest.NewRecorder()
	RespondJSON(w, http.StatusOK, map[string]string{"ok": "true"})
	if ct := w.Header().Get("Content-Type"); !strings.HasPrefix(ct, "application/json") {
		t.Fatalf("want application/json, got %q", ct)
	}
}

func TestRespondJSONStatus(t *testing.T) {
	w := httptest.NewRecorder()
	RespondJSON(w, http.StatusCreated, nil)
	if w.Code != http.StatusCreated {
		t.Fatalf("want 201, got %d", w.Code)
	}
}

func TestRespondErrorStatus(t *testing.T) {
	w := httptest.NewRecorder()
	RespondError(w, "bad input")
	if w.Code != http.StatusBadRequest {
		t.Fatalf("want 400, got %d", w.Code)
	}
}

func TestRespondRedirectURL(t *testing.T) {
	w := httptest.NewRecorder()
	r := httptest.NewRequest("GET", "/old", nil)
	RespondRedirect(w, r, "/new")
	if loc := w.Header().Get("Location"); loc != "/new" {
		t.Fatalf("want /new, got %q", loc)
	}
}

func TestRespondRedirectCode(t *testing.T) {
	w := httptest.NewRecorder()
	r := httptest.NewRequest("GET", "/old", nil)
	RespondRedirect(w, r, "/new")
	if w.Code != http.StatusFound {
		t.Fatalf("want 302, got %d", w.Code)
	}
}
